struct Base { i32 x; i32 getX(const this) { return this.x; } }
struct Sub : Base { i32 y; }
export i32 grammar() {
  Sub s = Sub(3, 7);
  i32 a = s.getX();
  i32 b = s.x + s.y;
  bool flag = a < b;
  i32 r = flag ? b : a;
  i32 c = 0;
  for (i32 i = 0; i < 3; i++) {
    if (i == 1) { continue; }
    c += i;
  }
  i32 d = 0;
  do { d++; } while (d < 2);
  switch (d) {
    case 1: r += 0; break;
    case 2: r += 10; break;
  }
  while (c < 5) { c++; }
  i32 x = 0xFF;
  i64 y = 42 as i64;
  return r + c + d + x + six() + y as~ i32;
}

